import{_ as a,o as t,c as n,a6 as r}from"./chunks/framework.CKIbuWFA.js";const h=JSON.parse('{"title":"TikTools 4.2.2 build and recovery status","description":"","frontmatter":{"title":"TikTools 4.2.2 build and recovery status","docId":"releases.4.2.2","translationKey":"releases.4.2.2","locale":"en","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"2a82a33b45407681d8d052a8a16e40dbc83f6889b3e4874cf05f95cc4aa44896","translationRevision":"2a82a33b45407681d8d052a8a16e40dbc83f6889b3e4874cf05f95cc4aa44896","order":40},"headers":[],"relativePath":"en/releases/4.2.2.md","filePath":"en/releases/4.2.2.md","lastUpdated":1794596859000}'),s={name:"en/releases/4.2.2.md"};function i(o,e,l,d,c,u){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="tiktools-422" tabindex="-1">TikTools 4.2.2 <a class="header-anchor" href="#tiktools-422" aria-label="Permalink to &quot;TikTools 4.2.2 {#tiktools-422}&quot;">​</a></h1><h2 id="goal-publication-status-and-prerequisites" tabindex="-1">Goal, publication status and prerequisites <a class="header-anchor" href="#goal-publication-status-and-prerequisites" aria-label="Permalink to &quot;Goal, publication status and prerequisites {#goal-publication-status-and-prerequisites}&quot;">​</a></h2><p>Use these notes to review the implemented Variables changes and the release&#39;s remaining gates. Status reported on 13 November 2026: <strong>application compilation and CI checks are green; Linux installers now package successfully and Windows packaging passed, but the AppImage startup gate failed on a missing XKB runtime dependency and 4.2.2 is not published</strong>. No successful installer publication, uploaded checksum verification or update-feed promotion is claimed.</p><p>The build runs in <code>hernan-lc/TikTools-app</code> with <code>RELEASE_REPO=nglmercer/TikTools-app</code> as its intended publication target. Existing 4.2.1 candidate assets remain separate. For an available test release use the <a href="./4.2.1-rc.3.html">published RC3 prerelease</a>; check the <a href="https://github.com/nglmercer/TikTools-app/releases" target="_blank" rel="noreferrer">release list</a> for actual downloadable assets.</p><p>These Cloud and collaboration features remain experimental. Source/candidate testing requires a separately built matching host, an isolated profile, saved non-secret Variables, current Cloud session/consent and the advertised native bridge. See <a href="./../developer/setup.html">development setup</a>.</p><h2 id="implemented-variables-changes" tabindex="-1">Implemented Variables changes <a class="header-anchor" href="#implemented-variables-changes" aria-label="Permalink to &quot;Implemented Variables changes {#implemented-variables-changes}&quot;">​</a></h2><p>Variables uses the shared Changes panel. Send handles only selected saved native values; download refreshes only the cache. Applying a reviewed Cloud value and withdrawing its Cloud copy are separate actions. Withdrawal retains the local value and secret classification. Unsaved local drafts must be saved or discarded first, and older hosts without the bridge hide the control.</p><p>The host checks exact session, consent, local revision and target comparison. Queued edits can be replaced or cancelled. Epoch-fenced recovery handles uncertain uploads and withdrawal after a value becomes secret without replaying its previous value. Decision generations advance after acknowledgement. Unchecked Variables and other section queues remain outside the selected send.</p><p>Large integer values retain exact native text across browser editing and comparison/adoption. Saving an unrelated variable preserves untouched integer text. Types remain text, number, boolean, list and local secret. Secret or blocked values have no value diff, send or adopt control. This adapter has no field merge, force, history or autosync control.</p><h2 id="review-steps-and-expected-result" tabindex="-1">Review steps and expected result <a class="header-anchor" href="#review-steps-and-expected-result" aria-label="Permalink to &quot;Review steps and expected result {#review-steps-and-expected-result}&quot;">​</a></h2><ol><li>In an isolated matching candidate, save a harmless text value such as <code>demoGreeting = &quot;Hello&quot;</code>. Saving alone should stay local.</li><li>Open Variables → Changes when the host announces support. Review the saved local/Cloud comparison and choose only the intended row for Send.</li><li>Treat download as a cache update. Review and Apply separately before expecting the local value to change.</li><li>Use explicit withdrawal to remove a Cloud copy. The local value and its secret classification should remain intact.</li><li>If session, consent, revision or a target changes, refresh the comparison and review again. Resolve an uncertain outcome through its existing recovery path rather than repeating an upload as a new operation.</li></ol><p>These are expected source behaviors, not newly executed production acceptance results.</p><h2 id="ci-corrections-recovery-and-unfinished-work" tabindex="-1">CI corrections, recovery and unfinished work <a class="header-anchor" href="#ci-corrections-recovery-and-unfinished-work" aria-label="Permalink to &quot;CI corrections, recovery and unfinished work {#ci-corrections-recovery-and-unfinished-work}&quot;">​</a></h2><p>The source corrects test-module ordering, a lifecycle fixture&#39;s prerelease SemVer opt-in and a test server&#39;s bounded complete-header read. Production plugin compatibility policy remains unchanged. The release workflow requires Linux AppImage startup with an isolated profile, installer content checks, immutable upload, downloaded checksums and signed-feed publication. The <a href="https://github.com/hernan-lc/TikTools-app/actions/runs/43469055839" target="_blank" rel="noreferrer">recovery run</a> generated Linux installers after preventing nested linuxdeploy cleanup from deleting its parent&#39;s extraction directory. Its next check incorrectly required a FUSE installation classification while using extract-and-run. Recovery tooling now distinguishes extracted startup from mounted installation; the native updater still rejects extracted layouts. The <a href="https://github.com/hernan-lc/TikTools-app/actions/runs/43484544700" target="_blank" rel="noreferrer">single authorized rerun</a> passed packaging and both CLI probes, then failed before frontend-ready because libxkbcommon-x11 could not be loaded. Its remaining work was cancelled to avoid spending minutes on a publication that could no longer proceed. The fix installs the XKB packages and bundles the dynamically loaded library with its dependencies; local Ubuntu loading checks pass. A complete corrected AppImage startup and release publication are still unverified; no further Actions run has been started.</p><p>Until packaging recovery and verified publication finish, use published assets and follow the <a href="./../user/updates.html">updates guide</a>. Keep profile backups; replacing a binary does not undo database migrations. For Variables failures preserve pending state, version and redacted request/error details using <a href="./../user/preferences/troubleshooting.html">Diagnostics</a>.</p><p>Teams nickname discovery and recipient-bound invitations still depend on backend <code>6a69c99</code> and migration <code>20261113000001_remote_invitation_recipients.sql</code>. This application build does not deploy the backend. Automations Cloud transport, Overlay revisions, history/branch provenance and remaining collaboration presentation work are separate. The historical LIVE SQLite lock holder remains unidentified. Local/fake-account checks do not establish signed-in production sync or Teams compatibility.</p><p>The <a href="https://github.com/nglmercer/TikTools-app/blob/80c5cb1fbfa45eaeb1c086c71320a15e565d8541/docs/RELEASE-4.2.2.md" target="_blank" rel="noreferrer">original release record</a> is retained as dated evidence. Return to the <a href="./">release index</a>.</p>',17)])])}const b=a(s,[["render",i]]);export{h as __pageData,b as default};
